import random, sys
import problems
from reduce import reduce as reduce_instance

def exact_cover_bruteforce(instance):
    u = instance['universe_size']
    sets = instance['sets']
    n = len(sets)
    masks=[]
    for s in sets:
        mask=0
        for e in s:
            mask|=1<<e
        masks.append(mask)
    full=(1<<u)-1
    for choose in range(1<<n):
        union=0
        ok=True
        for i in range(n):
            if choose>>i &1:
                if union & masks[i]:
                    ok=False;break
                union|=masks[i]
        if ok and union==full:
            return True
    return False

def sat_bruteforce(inst):
    m=inst['num_vars']
    clauses=inst['clauses']
    from itertools import product
    for assign in product([False,True], repeat=m):
        sat=True
        for clause in clauses:
            clause_sat=False
            for lit in clause:
                var=abs(lit)-1
                val=assign[var]
                if lit>0 and val:
                    clause_sat=True;break
                if lit<0 and not val:
                    clause_sat=True;break
            if not clause_sat:
                sat=False;break
        if sat:
            return True
    return False

random.seed(1)
for i in range(10000):
    u=random.randint(0,4)
    s=random.randint(0,5)
    sets=[]
    for _ in range(s):
        subset=[e for e in range(u) if random.choice([True,False])]
        sets.append(subset)
    inst={'universe_size':u,'sets':sets}
    problems.ExactCover.validate(inst)
    ec=exact_cover_bruteforce(inst)
    red=reduce_instance(inst)
    problems.Sat.validate(red)
    sat=sat_bruteforce(red)
    if ec!=sat:
        print('Mismatch at',inst)
        print('ExactCover',ec,'Sat',sat)
        print('Reduced',red)
        sys.exit(0)
print('No mismatches')
